def copy_stage_assignments_to_sections(apps, schema_editor):
    APISection = apps.get_model('APIConnectApp', 'APISection')
    ProcessStage = apps.get_model('APIConnectApp', 'ProcessStage')
    for section in APISection.objects.all().iterator():
        assignments = dict(
            ProcessStage.objects.filter(section_id=section.pk, order__in=(5, 6))
            .values_list('order', 'responsible_user_id')
        )
        section.specialist_teacher_id = assignments.get(5)
        section.ctp_coordinator_id = assignments.get(6)
        section.save(update_fields=['specialist_teacher', 'ctp_coordinator'])


def restore_section_assignments_to_stages(apps, schema_editor):
    APISection = apps.get_model('APIConnectApp', 'APISection')
    ProcessStage = apps.get_model('APIConnectApp', 'ProcessStage')
    for section in APISection.objects.all().iterator():
        ProcessStage.objects.filter(section_id=section.pk, order=5).update(
            responsible_role='DE', responsible_user_id=section.specialist_teacher_id
        )
        ProcessStage.objects.filter(section_id=section.pk, order=6).update(
            responsible_role='CTP', responsible_user_id=section.ctp_coordinator_id
        )
        ProcessStage.objects.filter(section_id=section.pk).exclude(order__in=(5, 6)).update(
            responsible_role='DC', responsible_user_id=section.career_director_id
        )


